/**
 * Items the user sent while no recipient was available. Kept in IndexedDB on
 * the sender's own device (localStorage can't hold files), so they survive a
 * reload and never leave the device until the user sends them to someone.
 */
export type OutboxItem =
  | { id: string; createdAt: number; kind: "text"; text: string }
  | { id: string; createdAt: number; kind: "files"; files: File[] };

const DB_NAME = "landrop";
const STORE = "outbox";

function openDb(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, 1);
    request.onupgradeneeded = () => request.result.createObjectStore(STORE, { keyPath: "id" });
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

async function run<T>(mode: IDBTransactionMode, op: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  const db = await openDb();
  try {
    return await new Promise<T>((resolve, reject) => {
      const tx = db.transaction(STORE, mode);
      const request = op(tx.objectStore(STORE));
      tx.oncomplete = () => resolve(request.result);
      tx.onerror = () => reject(tx.error);
      tx.onabort = () => reject(tx.error ?? new Error("Storage write was aborted"));
    });
  } finally {
    db.close();
  }
}

export async function loadOutbox(): Promise<OutboxItem[]> {
  const items = await run("readonly", (store) => store.getAll() as IDBRequest<OutboxItem[]>);
  return items.sort((a, b) => a.createdAt - b.createdAt);
}

export const saveOutboxItem = (item: OutboxItem) => run("readwrite", (store) => store.put(item));

export const deleteOutboxItem = (id: string) => run("readwrite", (store) => store.delete(id));
