"use client";

import { createSHA256 } from "hash-wasm";
import { useEffect, useReducer, useRef, useState } from "react";
import {
  DEFAULT_LAN_PORT,
  PROTOCOL_VERSION,
  TERMINAL_STATUSES,
  routes,
  type ClientMessage,
  type Device,
  type ServerEvent,
  type Transfer,
  type TransferProgress,
} from "@landrop/protocol";
import { deleteOutboxItem, loadOutbox, saveOutboxItem, type OutboxItem } from "./outbox";

const LAN_PORT = Number(process.env.NEXT_PUBLIC_LANDROP_PORT ?? DEFAULT_LAN_PORT);
const HASH_SLICE_BYTES = 8 * 1024 * 1024;
const RECONNECT_MS = 2000;

interface Message {
  peerId: string;
  text: string;
  at: number;
  outgoing: boolean;
}

interface State {
  connection: "connecting" | "online" | "offline";
  self?: Device;
  token?: string;
  devices: Device[];
  transfers: Record<string, Transfer>;
  progress: Record<string, TransferProgress>;
  messages: Message[];
  notice?: string;
}

type Action =
  | { type: "event"; event: ServerEvent }
  | { type: "disconnected" }
  | { type: "transfer"; transfer: Transfer }
  | { type: "message"; message: Message }
  | { type: "notice"; notice?: string };

const initialState: State = { connection: "connecting", devices: [], transfers: {}, progress: {}, messages: [] };

function reducer(state: State, action: Action): State {
  switch (action.type) {
    case "disconnected":
      // A new session gets a new identity; the server cancelled this session's open transfers.
      return { ...initialState, connection: "offline", messages: state.messages };
    case "transfer":
      return { ...state, transfers: { ...state.transfers, [action.transfer.manifest.id]: action.transfer } };
    case "message":
      return { ...state, messages: [action.message, ...state.messages] };
    case "notice":
      return { ...state, notice: action.notice };
    case "event": {
      const e = action.event;
      switch (e.type) {
        case "session:welcome":
          return { ...state, connection: "online", self: e.self, token: e.token, devices: e.devices };
        case "device:discovered":
          return { ...state, devices: [...state.devices.filter((d) => d.id !== e.device.id), e.device] };
        case "device:offline":
          return { ...state, devices: state.devices.filter((d) => d.id !== e.deviceId) };
        case "text:received":
          return { ...state, messages: [{ peerId: e.from, text: e.text, at: e.sentAt, outgoing: false }, ...state.messages] };
        case "transfer:progress":
          return { ...state, progress: { ...state.progress, [e.progress.transferId]: e.progress } };
        case "error":
          return { ...state, notice: e.message };
        default:
          return { ...state, transfers: { ...state.transfers, [e.transfer.manifest.id]: e.transfer } };
      }
    }
  }
}

export default function LanDrop() {
  const [state, dispatch] = useReducer(reducer, initialState);
  const [targetId, setTargetId] = useState<string>();
  const [text, setText] = useState("");
  const [files, setFiles] = useState<File[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [outbox, setOutbox] = useState<OutboxItem[]>([]);
  const socketRef = useRef<WebSocket | null>(null);
  const tokenRef = useRef<string | undefined>(undefined);
  const selfRef = useRef<Device | undefined>(undefined);
  /** Files waiting for the receiver's consent, by transfer id. */
  const outgoingRef = useRef(new Map<string, File[]>());
  /** Uploads in progress, so they can be stopped when the transfer ends. */
  const uploadsRef = useRef(new Map<string, { stopped: boolean; xhr?: XMLHttpRequest }>());

  const serverBase = () => `${location.protocol}//${location.hostname}:${LAN_PORT}`;

  async function api<T>(path: string, method: string, body?: unknown): Promise<T> {
    const res = await fetch(serverBase() + path, {
      method,
      headers: {
        authorization: `Bearer ${tokenRef.current}`,
        ...(body !== undefined && { "content-type": "application/json" }),
      },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
    const json = await res.json().catch(() => ({}));
    if (!res.ok) throw new Error(json.message ?? `Request failed (${res.status})`);
    return json as T;
  }

  async function runUpload(transfer: Transfer) {
    const id = transfer.manifest.id;
    const local = outgoingRef.current.get(id);
    outgoingRef.current.delete(id);
    if (!local) return;
    const control: { stopped: boolean; xhr?: XMLHttpRequest } = { stopped: false };
    uploadsRef.current.set(id, control);
    try {
      for (const [index, entry] of transfer.manifest.files.entries()) {
        const file = local[index];
        // Upload and hash in parallel: the server hashes what arrives, we hash the original.
        const [, sha256] = await Promise.all([
          putFile(routes.fileData(id, entry.id), file, control),
          hashFile(file, control),
        ]);
        await api(routes.fileChecksum(id, entry.id), "POST", { sha256 });
      }
    } catch (err) {
      if (!control.stopped) dispatch({ type: "notice", notice: `Sending failed: ${(err as Error).message}` });
    } finally {
      uploadsRef.current.delete(id);
    }
  }

  function putFile(path: string, file: File, control: { stopped: boolean; xhr?: XMLHttpRequest }) {
    return new Promise<void>((resolve, reject) => {
      const xhr = new XMLHttpRequest();
      control.xhr = xhr;
      xhr.open("PUT", serverBase() + path);
      xhr.setRequestHeader("authorization", `Bearer ${tokenRef.current}`);
      xhr.setRequestHeader("content-type", "application/octet-stream");
      xhr.onload = () =>
        xhr.status < 300 ? resolve() : reject(new Error(safeMessage(xhr.responseText) ?? `HTTP ${xhr.status}`));
      xhr.onerror = () => reject(new Error("Connection to the host was lost"));
      xhr.onabort = () => reject(new Error("Upload stopped"));
      // The browser streams the File from disk; it is never read into memory here.
      xhr.send(file);
    });
  }

  useEffect(() => {
    let disposed = false;
    let retry: ReturnType<typeof setTimeout>;

    const open = () => {
      const scheme = location.protocol === "https:" ? "wss" : "ws";
      const socket = new WebSocket(`${scheme}://${location.hostname}:${LAN_PORT}${routes.ws}`);
      socketRef.current = socket;
      socket.onopen = () => {
        const hello: ClientMessage = { type: "hello", protocolVersion: PROTOCOL_VERSION, name: defaultDeviceName() };
        socket.send(JSON.stringify(hello));
      };
      socket.onmessage = (raw) => {
        const event = JSON.parse(raw.data) as ServerEvent;
        if (event.type === "session:welcome") {
          tokenRef.current = event.token;
          selfRef.current = event.self;
        }
        if ("transfer" in event) {
          const id = event.transfer.manifest.id;
          if (event.type === "transfer:accepted" && event.transfer.manifest.senderId === selfRef.current?.id) {
            void runUpload(event.transfer);
          }
          if (TERMINAL_STATUSES.has(event.transfer.status)) {
            outgoingRef.current.delete(id);
            const upload = uploadsRef.current.get(id);
            if (upload && event.transfer.status !== "completed") {
              upload.stopped = true;
              upload.xhr?.abort();
            }
          }
        }
        dispatch({ type: "event", event });
      };
      socket.onclose = () => {
        if (disposed) return;
        tokenRef.current = undefined;
        selfRef.current = undefined;
        outgoingRef.current.clear();
        for (const upload of uploadsRef.current.values()) {
          upload.stopped = true;
          upload.xhr?.abort();
        }
        dispatch({ type: "disconnected" });
        retry = setTimeout(open, RECONNECT_MS);
      };
    };
    open();
    return () => {
      disposed = true;
      clearTimeout(retry);
      socketRef.current?.close();
    };
    // runUpload only reads refs, so the socket is opened once per mount.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    loadOutbox()
      .then(setOutbox)
      .catch(() => dispatch({ type: "notice", notice: "This browser can't keep unsent items; they'll be lost on reload." }));
  }, []);

  // With a single nearby device there is nothing to choose, so it is the target.
  const target =
    state.devices.find((d) => d.id === targetId) ?? (state.devices.length === 1 ? state.devices[0] : undefined);
  const nameOf = (id: string) =>
    id === state.self?.id ? "You" : (state.devices.find((d) => d.id === id)?.name ?? "Disconnected device");

  function deliverText(to: Device, body: string) {
    const message: ClientMessage = { type: "text:send", to: to.id, text: body };
    socketRef.current?.send(JSON.stringify(message));
    dispatch({ type: "message", message: { peerId: to.id, text: body, at: Date.now(), outgoing: true } });
  }

  async function deliverFiles(to: Device, selected: File[]) {
    const transfer = await api<Transfer>(routes.transfers, "POST", {
      receiverId: to.id,
      files: selected.map((f) => ({ name: f.name, size: f.size, mimeType: f.type || "application/octet-stream" })),
    });
    outgoingRef.current.set(transfer.manifest.id, selected);
    dispatch({ type: "transfer", transfer });
  }

  /** No recipient yet: keep the item on this device until the user sends it to someone. */
  async function queue(item: { kind: "text"; text: string } | { kind: "files"; files: File[] }) {
    const full = { ...item, id: `${Date.now()}-${Math.random().toString(36).slice(2)}`, createdAt: Date.now() } as OutboxItem;
    setOutbox((items) => [...items, full]);
    try {
      await saveOutboxItem(full);
    } catch {
      dispatch({ type: "notice", notice: "Couldn't save to this device's storage; the item is kept only until you reload." });
    }
  }

  async function removeFromOutbox(id: string) {
    setOutbox((items) => items.filter((i) => i.id !== id));
    await deleteOutboxItem(id).catch(() => undefined);
  }

  async function sendOutbox(to: Device) {
    for (const item of outbox) {
      try {
        if (item.kind === "text") deliverText(to, item.text);
        else await deliverFiles(to, item.files);
        await removeFromOutbox(item.id);
      } catch (err) {
        return dispatch({ type: "notice", notice: `Sending from Outbox stopped: ${(err as Error).message}` });
      }
    }
  }

  async function sendText() {
    if (!text.trim()) return dispatch({ type: "notice", notice: "Type a message or link first." });
    if (target) deliverText(target, text);
    else await queue({ kind: "text", text });
    setText("");
    dispatch({ type: "notice" });
  }

  async function sendFiles() {
    if (files.length === 0) return dispatch({ type: "notice", notice: "Choose a file first." });
    try {
      if (target) await deliverFiles(target, files);
      else await queue({ kind: "files", files });
      setFiles([]);
      if (fileInputRef.current) fileInputRef.current.value = "";
      dispatch({ type: "notice" });
    } catch (err) {
      dispatch({ type: "notice", notice: (err as Error).message });
    }
  }

  async function act(transferId: string, action: "accept" | "reject" | "cancel") {
    try {
      dispatch({ type: "transfer", transfer: await api<Transfer>(routes[action](transferId), "POST") });
    } catch (err) {
      dispatch({ type: "notice", notice: (err as Error).message });
    }
  }

  const transfers = Object.values(state.transfers).sort((a, b) => b.manifest.createdAt - a.manifest.createdAt);

  return (
    <main className="mx-auto flex w-full max-w-3xl flex-col gap-6 px-4 py-8">
      <header className="flex flex-wrap items-baseline justify-between gap-2">
        <h1 className="text-2xl font-semibold tracking-tight">LANDrop</h1>
        <p className="text-sm text-muted">
          <span
            className={`mr-2 inline-block size-2 rounded-full ${
              state.connection === "online" ? "bg-emerald-500" : state.connection === "connecting" ? "bg-amber-500" : "bg-red-500"
            }`}
          />
          {state.connection === "online"
            ? `You are ${state.self?.name} · ${shortId(state.self!.id)}`
            : state.connection === "connecting"
              ? "Connecting to host…"
              : `Can't reach the LANDrop host on port ${LAN_PORT}. Retrying…`}
        </p>
      </header>

      {state.notice && (
        <div role="alert" className="flex items-start justify-between gap-4 rounded-lg border border-red-500/40 bg-red-500/10 px-4 py-3 text-sm">
          <span>{state.notice}</span>
          <button className="text-muted hover:underline" onClick={() => dispatch({ type: "notice" })}>
            Dismiss
          </button>
        </div>
      )}

      <section aria-labelledby="devices-heading" className="flex flex-col gap-3">
        <h2 id="devices-heading" className="text-sm font-medium uppercase tracking-wide text-muted">
          Nearby devices
        </h2>
        {state.devices.length === 0 ? (
          <p className="rounded-lg border border-dashed border-line px-4 py-6 text-sm text-muted">
            No other devices yet. Open this page on another device on the same network.
          </p>
        ) : (
          <ul className="grid gap-2 sm:grid-cols-2">
            {state.devices.map((d) => (
              <li key={d.id}>
                <button
                  onClick={() => setTargetId(d.id)}
                  aria-pressed={d.id === target?.id}
                  className={`w-full rounded-lg border px-4 py-3 text-left transition-colors ${
                    d.id === target?.id ? "border-accent bg-accent/10" : "border-line hover:border-accent/60"
                  }`}
                >
                  <span className="block font-medium">{d.name}</span>
                  <span className="text-xs text-muted">{shortId(d.id)}</span>
                </button>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-label="Send" className="flex flex-col gap-3 rounded-lg border border-line p-4">
        <p className="text-sm text-muted">
          {target
            ? `Sending to ${target.name} · ${shortId(target.id)}`
            : state.devices.length === 0
              ? "No other device is online yet. What you send waits in your Outbox on this device."
              : "No device chosen. What you send waits in your Outbox until you tap a device above."}
        </p>
        <div className="flex flex-col gap-2 sm:flex-row">
          <textarea
            value={text}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                sendText();
              }
            }}
            rows={2}
            placeholder="Text or a link"
            aria-label="Text to send"
            className="min-h-11 flex-1 resize-y rounded-md border border-line bg-transparent px-3 py-2"
          />
          <button onClick={sendText} className="btn">
            Send text
          </button>
        </div>
        <div className="flex flex-col gap-2 sm:flex-row sm:items-center">
          <input
            ref={fileInputRef}
            type="file"
            multiple
            aria-label="Files to send"
            onChange={(e) => setFiles([...(e.target.files ?? [])])}
            className="flex-1 text-sm file:mr-3 file:rounded-md file:border file:border-line file:bg-transparent file:px-3 file:py-1.5"
          />
          <button onClick={sendFiles} className="btn">
            Send {files.length > 1 ? `${files.length} files` : "file"}
          </button>
        </div>
      </section>

      {outbox.length > 0 && (
        <section aria-labelledby="outbox-heading" className="flex flex-col gap-3">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <h2 id="outbox-heading" className="text-sm font-medium uppercase tracking-wide text-muted">
              Outbox · saved on this device
            </h2>
            {target && (
              <button className="btn" onClick={() => sendOutbox(target)}>
                Send all to {target.name} · {shortId(target.id)}
              </button>
            )}
          </div>
          <ul className="flex flex-col gap-2">
            {outbox.map((item) => (
              <li key={item.id} className="flex items-start justify-between gap-3 rounded-lg border border-line px-4 py-3">
                <p className="min-w-0 whitespace-pre-wrap wrap-break-word">
                  {item.kind === "text"
                    ? item.text
                    : item.files.map((f) => `${f.name} (${formatBytes(f.size)})`).join(", ")}
                </p>
                <button className="btn-secondary shrink-0" onClick={() => removeFromOutbox(item.id)} aria-label="Remove from Outbox">
                  Remove
                </button>
              </li>
            ))}
          </ul>
        </section>
      )}

      {transfers.length > 0 && (
        <section aria-labelledby="transfers-heading" className="flex flex-col gap-3">
          <h2 id="transfers-heading" className="text-sm font-medium uppercase tracking-wide text-muted">
            Transfers
          </h2>
          <ul className="flex flex-col gap-2">
            {transfers.map((t) => (
              <TransferCard
                key={t.manifest.id}
                transfer={t}
                progress={state.progress[t.manifest.id]}
                incoming={t.manifest.receiverId === state.self?.id}
                peerName={nameOf(t.manifest.receiverId === state.self?.id ? t.manifest.senderId : t.manifest.receiverId)}
                downloadUrl={(fileId) => `${serverBase()}${routes.fileDownload(t.manifest.id, fileId)}?token=${state.token}`}
                onAction={(action) => act(t.manifest.id, action)}
              />
            ))}
          </ul>
        </section>
      )}

      {state.messages.length > 0 && (
        <section aria-labelledby="messages-heading" className="flex flex-col gap-3">
          <h2 id="messages-heading" className="text-sm font-medium uppercase tracking-wide text-muted">
            Messages
          </h2>
          <ul className="flex flex-col gap-2">
            {state.messages.map((m, i) => (
              <li key={`${m.at}-${i}`} className="rounded-lg border border-line px-4 py-3">
                <p className="mb-1 text-xs text-muted">
                  {m.outgoing ? `To ${nameOf(m.peerId)}` : `From ${nameOf(m.peerId)}`} · {new Date(m.at).toLocaleTimeString()}
                </p>
                <p className="whitespace-pre-wrap wrap-break-word select-all">{m.text}</p>
              </li>
            ))}
          </ul>
        </section>
      )}
    </main>
  );
}

function TransferCard({
  transfer,
  progress,
  incoming,
  peerName,
  downloadUrl,
  onAction,
}: {
  transfer: Transfer;
  progress?: TransferProgress;
  incoming: boolean;
  peerName: string;
  downloadUrl: (fileId: string) => string;
  onAction: (action: "accept" | "reject" | "cancel") => void;
}) {
  const { manifest, status } = transfer;
  const done = progress?.bytesTransferred ?? 0;
  const fraction = manifest.totalSize > 0 ? done / manifest.totalSize : status === "completed" ? 1 : 0;
  const active = status === "accepted" && progress && done < manifest.totalSize;
  const remaining = active && progress.bytesPerSecond > 0 ? (manifest.totalSize - done) / progress.bytesPerSecond : undefined;
  const title = manifest.files.length === 1 ? manifest.files[0].name : `${manifest.files.length} files`;

  return (
    <li className="flex flex-col gap-2 rounded-lg border border-line px-4 py-3">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <p className="min-w-0 break-all font-medium">{title}</p>
        <p className="text-xs text-muted">
          {incoming ? `From ${peerName}` : `To ${peerName}`} · {formatBytes(manifest.totalSize)} · {statusLabel(transfer, incoming)}
        </p>
      </div>

      {status === "accepted" || status === "completed" ? (
        <>
          <div
            role="progressbar"
            aria-valuemin={0}
            aria-valuemax={100}
            aria-valuenow={Math.round(fraction * 100)}
            className="h-1.5 overflow-hidden rounded-full bg-line"
          >
            <div className="h-full bg-accent transition-[width]" style={{ width: `${fraction * 100}%` }} />
          </div>
          {active && (
            <p className="text-xs tabular-nums text-muted">
              {Math.floor(fraction * 100)}% · {formatBytes(progress.bytesPerSecond)}/s
              {remaining !== undefined && ` · ${formatDuration(remaining)} left`}
            </p>
          )}
        </>
      ) : null}

      {transfer.error && <p className="text-sm text-red-600 dark:text-red-400">{transfer.error}</p>}

      <div className="flex flex-wrap gap-2">
        {incoming && status === "pending" && (
          <>
            <button className="btn" onClick={() => onAction("accept")}>
              Accept
            </button>
            <button className="btn-secondary" onClick={() => onAction("reject")}>
              Decline
            </button>
          </>
        )}
        {(status === "accepted" || (!incoming && status === "pending")) && (
          <button className="btn-secondary" onClick={() => onAction("cancel")}>
            Cancel
          </button>
        )}
      </div>

      {incoming && status === "completed" && (
        <ul className="flex flex-col gap-1 text-sm">
          {manifest.files.map((f) => (
            <li key={f.id} className="flex flex-wrap items-baseline justify-between gap-2">
              <a href={downloadUrl(f.id)} download={f.name} className="break-all text-accent underline-offset-2 hover:underline">
                Save {f.name}
              </a>
              <span className="font-mono text-xs text-muted" title={`SHA-256 ${transfer.files[f.id].sha256}`}>
                SHA-256 verified · {transfer.files[f.id].sha256?.slice(0, 12)}…
              </span>
            </li>
          ))}
        </ul>
      )}
    </li>
  );
}

async function hashFile(file: File, control: { stopped: boolean }): Promise<string> {
  const hasher = await createSHA256();
  hasher.init();
  for (let offset = 0; offset < file.size; offset += HASH_SLICE_BYTES) {
    if (control.stopped) throw new Error("Stopped");
    // One slice in memory at a time; awaiting each read keeps the UI responsive.
    hasher.update(new Uint8Array(await file.slice(offset, offset + HASH_SLICE_BYTES).arrayBuffer()));
  }
  return hasher.digest("hex");
}

function statusLabel(transfer: Transfer, incoming: boolean): string {
  switch (transfer.status) {
    case "pending":
      return incoming ? "Wants to send you this" : "Waiting for them to accept";
    case "accepted":
      return incoming ? "Receiving" : "Sending";
    case "completed":
      return "Done";
    case "rejected":
      return "Declined";
    case "cancelled":
      return "Cancelled";
    case "failed":
      return "Failed";
  }
}

function safeMessage(body: string): string | undefined {
  try {
    return JSON.parse(body).message;
  } catch {
    return undefined;
  }
}

function defaultDeviceName(): string {
  const ua = navigator.userAgent;
  const os = /iPhone/.test(ua)
    ? "iPhone"
    : /iPad/.test(ua)
      ? "iPad"
      : /Android/.test(ua)
        ? "Android"
        : /Mac OS X/.test(ua)
          ? "Mac"
          : /Windows/.test(ua)
            ? "Windows"
            : /Linux/.test(ua)
              ? "Linux"
              : "Device";
  const browser = /Edg\//.test(ua)
    ? "Edge"
    : /Firefox\//.test(ua)
      ? "Firefox"
      : /Chrome\//.test(ua)
        ? "Chrome"
        : /Safari\//.test(ua)
          ? "Safari"
          : "Browser";
  return `${browser} on ${os}`;
}

const shortId = (id: string) => `#${id.slice(0, 4)}`;

function formatBytes(bytes: number): string {
  const units = ["B", "KB", "MB", "GB", "TB"];
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit++;
  }
  return `${value.toFixed(unit === 0 || value >= 100 ? 0 : 1)} ${units[unit]}`;
}

function formatDuration(seconds: number): string {
  if (seconds < 60) return `${Math.ceil(seconds)}s`;
  const m = Math.floor(seconds / 60);
  return `${m}m ${Math.ceil(seconds % 60)}s`;
}
